83	export function restoreFromBranch(branch: string, targetPath: string): string | undefined {
84	  if (gitRun("fetch", "origin", branch, "--depth=1").code !== 0) return undefined;
85	  if (gitRun("cat-file", "-e", `origin/${branch}:${targetPath}`).code !== 0) return undefined;
