90	/**
91	 * Write one file as the ONLY commit on `branch`, discarding whatever was there.
92	 *
93	 * For data that is rewritten whole, whose old versions are worth nothing, and which
94	 * can be rebuilt if it is lost. The issue search index is all three -- see
95	 * `adapters/github/issue-index.ts` for what keeping its history cost before this existed.
96	 *
97	 * # Why this does not use a worktree
98	 *
99	 * `saveSession` checks out a worktree because it edits a tree it must preserve. There
100	 * is nothing to preserve here: the commit has no parent and one file, so it can be
101	 * built out of plumbing -- a blob, a tree, a commit -- without a checkout, an index,
102	 * or a second copy of anything on disk. That also means it cannot disturb the agent's
103	 * own checkout, which at this point in a run may hold uncommitted work.
104	 *
105	 * # Why the force-push is safe here and would not be on `atomaton-data`
106	 *
107	 * Nothing else is on this branch. A force-push that loses a concurrent write loses
108	 * one refresh of an index that the next call rebuilds from `?since=`; the same
109	 * force-push on `atomaton-data` would drop a session that nothing can reconstruct.
110	 */
111	export function saveAsOnlyCommit(
112	  branch: string,
113	  targetPath: string,
114	  content: string,
115	  commitMessage: string,
116	): boolean {
117	  // commit-tree takes the committer from config, which is not set in a fresh
118	  // checkout; the same two lines `saveSession` runs before it creates the branch.
119	  gitRun("config", "user.email", "action@github.com");
120	  gitRun("config", "user.name", "GitHub Actions");
121	
122	  const blob = gitPipe(content, "hash-object", "-w", "--stdin");
123	  if (blob.code !== 0) return false;
124	  const tree = gitPipe(`100644 blob ${blob.stdout}\t${targetPath}\n`, "mktree");
125	  if (tree.code !== 0) return false;
126	  // No parent: the branch is one commit, now and after every later save.
127	  const commit = gitPipe(commitMessage, "commit-tree", tree.stdout);
128	  if (commit.code !== 0) return false;
129	
130	  return gitRun("push", "--force", "origin", `${commit.stdout}:refs/heads/${branch}`).code === 0;
131	}
