148	 * content was already identical -- a no-op "save").
149	 */
150	export function saveSession(targetPath: string, content: string, commitMessage: string): boolean {
151	  if (gitRun("ls-remote", "--exit-code", "origin", DATA_BRANCH).code !== 0) {
152	    gitRun("config", "user.email", "action@github.com");
153	    gitRun("config", "user.name", "GitHub Actions");
154	    // 4b825dc6... is Git's canonical empty-tree SHA (never changes).
155	    const commit = gitRun("commit-tree", "4b825dc642cb6eb9a060e54bf8d69288fbee4904", "-m", `init: ${DATA_BRANCH} session store`).stdout;
156	    gitRun("push", "origin", `${commit}:refs/heads/${DATA_BRANCH}`);
157	  }
158	
159	  gitRun("fetch", "origin", DATA_BRANCH);
160	  const worktreeDir = mkdtempSync(join(tmpdir(), "atomaton-data-wt-"));
161	  gitRun("worktree", "add", worktreeDir, `origin/${DATA_BRANCH}`);
